const yaml = require('js-yaml');

const baselineText = $input.first().json.stdout;
const baseline = yaml.load(baselineText);

// ---- gesetz: validate IDs/ports from baseline (Single Source of Truth)
const allowMin = baseline.port_policy?.allow_range?.min ?? 12344;
const allowMax = baseline.port_policy?.allow_range?.max ?? 12399;
const forbidden = new Set(baseline.port_policy?.forbidden_ports ?? [8080]);

const agents = baseline.agents || [];

// validate unique ports
const portSet = new Set();
for (const a of agents) {
  if (!a.id || !/^opena\d+$/.test(a.id)) {
    throw new Error(`INVALID_ID: ${a.id}`);
  }
  if (typeof a.port !== 'number') {
    throw new Error(`INVALID_PORT_TYPE: ${a.id} -> ${a.port}`);
  }
  if (a.port < allowMin || a.port > allowMax) {
    throw new Error(`PORT_OUT_OF_RANGE: ${a.id} -> ${a.port}`);
  }
  if (forbidden.has(a.port)) {
    throw new Error(`FORBIDDEN_PORT: ${a.id} -> ${a.port}`);
  }
  if (portSet.has(a.port)) {
    throw new Error(`PORT_CONFLICT: ${a.id} -> ${a.port}`);
  }
  portSet.add(a.port);
}

// target agents for dashboards (feature + workflow + system, but skip core opena1/2)
const targetAgents = [
  'opena3','opena4','opena5','opena6','opena7','opena8','opena9','opena10',
  'opena11','opena12','opena13','opena14','opena15','opena16','opena17','opena18','opena19','opena21'
];

const picked = agents.filter(a => targetAgents.includes(a.id));

return picked.map(a => ({
  json: {
    id: a.id,
    name: a.name,
    port: a.port,
    role: a.role,
    plan: a.plan,
    folder_path: a.folder_path,
    description: a.description || ''
  }
}));

const agent = $input.item.json;

const html = `<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${agent.name} (${agent.id}) – PORTIER Dashboard</title>
  <style>
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:system-ui,Segoe UI,Roboto,sans-serif;background:#0b1220;color:#e8eefc;padding:24px}
    .wrap{max-width:1200px;margin:0 auto}
    .card{background:#121b2f;border:1px solid #223056;border-radius:16px;padding:20px;margin-bottom:16px}
    .h{display:flex;align-items:center;justify-content:space-between;gap:12px}
    h1{font-size:22px}
    .meta{opacity:.85;font-size:13px}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-top:14px}
    .kpi{background:#0f1730;border:1px solid #223056;border-radius:14px;padding:14px}
    .kpi .l{opacity:.8;font-size:12px;margin-bottom:6px}
    .kpi .v{font-size:18px;font-weight:700}
    a{color:#8bb2ff;text-decoration:none}
    code{background:#0f1730;padding:3px 6px;border-radius:8px}
  </style>
</head>
<body>
  <div class="wrap">
    <div class="card">
      <div class="h">
        <div>
          <h1>${agent.name} <span class="meta">(${agent.id})</span></h1>
          <div class="meta">${agent.role} · Plan: <b>${String(agent.plan||'').toUpperCase()}</b></div>
          <div class="meta">Port: <b>${agent.port}</b> · Ordner: <code>${agent.folder_path}</code></div>
        </div>
        <div class="meta">Hosted by <b>opena20</b> (Control Plane)</div>
      </div>
      <div class="grid">
        <div class="kpi"><div class="l">Health</div><div class="v"><a href="http://localhost:${agent.port}/health" target="_blank">/health</a></div></div>
        <div class="kpi"><div class="l">Status</div><div class="v"><a href="http://localhost:${agent.port}/status" target="_blank">/status</a></div></div>
        <div class="kpi"><div class="l">Capabilities</div><div class="v"><a href="http://localhost:${agent.port}/api/capabilities" target="_blank">/api/capabilities</a></div></div>
        <div class="kpi"><div class="l">Execute</div><div class="v"><code>POST /api/execute</code></div></div>
      </div>
    </div>

    <div class="card">
      <div class="meta">Beschreibung</div>
      <div style="margin-top:10px;line-height:1.5">${agent.description || '—'}</div>
    </div>
  </div>
</body>
</html>`;

const html_b64 = Buffer.from(html, 'utf8').toString('base64');

return [{ json: { agent_id: agent.id, html_b64 } }];
